using System.Net;using System.Text.Json;namespace FCG.Games.Web.Middleware;public sealed class ExceptionMiddleware(RequestDelegate next,ILogger<ExceptionMiddleware> logger){public async Task InvokeAsync(HttpContext context){try{await next(context);}catch(Exception ex){logger.LogError(ex,"Erro não tratado");context.Response.ContentType="application/json";context.Response.StatusCode=ex switch{KeyNotFoundException=>(int)HttpStatusCode.NotFound,ArgumentException=>(int)HttpStatusCode.BadRequest,InvalidOperationException=>(int)HttpStatusCode.Conflict,UnauthorizedAccessException=>(int)HttpStatusCode.Unauthorized,_=>(int)HttpStatusCode.InternalServerError};await context.Response.WriteAsync(JsonSerializer.Serialize(new{error=ex.Message}));}}}
